-- US equity exchanges, other US equity venues, US listed derivatives, and the two placeholders
INSERT INTO ref_venue (mic, operating_mic, name, country, venue_type, lei)
SELECT r.mic, r.operating_mic, r.market_name, c.alpha2,
       CASE r.mic WHEN 'XXXX' THEN 'NONE' WHEN 'XOFF' THEN 'OTC' ELSE 'EXCHANGE' END,
       r.lei
FROM ref_mic_registry r
LEFT JOIN ref_country c ON c.alpha2 = r.country
WHERE r.mic IN ('XNYS', 'XNAS', 'XASE', 'ARCX', 'BATS', 'EDGX', 'IEXG',
                'XCBO', 'XCME', 'XCBT', 'IFUS', 'XXXX', 'XOFF');
